import java.util.*;

class Solution {
    public boolean hasCycle(int[] next) {
        if (next.length == 0) return false;
        int slow = 0, fast = 0;
        while (true) {
            if (next[fast] == -1 || next[next[fast]] == -1) return false; // trail ends
            slow = next[slow];             // tortoise: 1 step
            fast = next[next[fast]];       // hare: 2 steps
            if (slow == fast) return true; // hare lapped the tortoise
        }
    }
}

